cd /tmp/claude-0/-home-user/979e8242-2c77-5242-991d-0bed1baea8dd/scratchpad/e6/F5; cat > exegenius/tasks/0002-background.answer.json <<'EOF'
{
  "summary": "The reader has an undergraduate computer science education: discrete mathematics (sets, counting, induction, primes, gcd), a first algorithms course (divide and conquer, recurrences, sorting, Karatsuba multiplication, schoolbook arithmetic) and complexity (big-O family, single- and multitape Turing machines), together with calculus (exponentials, logarithms, series), linear algebra over the reals and complex numbers, and polynomials. They have not met Fourier transforms or the FFT in depth, finite fields beyond arithmetic mod 2, bilinear forms over arbitrary fields, number-theoretic estimates such as prime density, or any research-level multiplication algorithm; those are what the wiki must explain.",
  "known": [
    {
      "name": "Big-Theta, big-Omega and little-o notation",
      "aliases": ["Theta", "Omega", "Θ", "Ω", "little-o", "o(1)", "asymptotic notation"],
      "gloss": "Θ gives a two-sided asymptotic bound, Ω a lower bound, and o a strictly smaller order of growth, alongside O."
    },
    {
      "name": "Divide-and-conquer recurrences",
      "aliases": ["recurrence relation", "master theorem", "recursion tree", "solving recurrences"],
      "gloss": "A running time T(n) defined in terms of recursive calls on smaller inputs plus extra work, solved by unrolling or a recursion tree to a closed-form order of growth."
    },
    {
      "name": "Schoolbook and Karatsuba multiplication",
      "aliases": ["long multiplication", "Karatsuba", "Toom-Cook", "grade-school multiplication"],
      "gloss": "Quadratic-time digit-by-digit multiplication and Karatsuba's O(n^1.585) method that replaces four half-size products by three."
    },
    {
      "name": "Positional notation in any radix and mixed radix",
      "aliases": ["radix-q digits", "base-q representation", "mixed-radix expansion", "digit string", "most significant digit"],
      "gloss": "Writing an integer as a digit string in base q, or with a different base at each position, with place values given by products of the bases."
    },
    {
      "name": "Bitwise operations, XOR and Hamming weight",
      "aliases": ["XOR", "exclusive or", "addition mod 2", "bit parity", "wt", "popcount", "Hamming weight"],
      "gloss": "Bitwise XOR is addition of bits modulo 2, and the Hamming weight of a bit vector is the number of its 1 bits."
    },
    {
      "name": "Floor, ceiling and rounding",
      "aliases": ["⌊x⌋", "⌈x⌉", "round to nearest integer", "integer part"],
      "gloss": "The greatest integer at most x, the least integer at least x, and the nearest integer to x."
    },
    {
      "name": "Exponential and logarithm functions",
      "aliases": ["log base 2", "lg", "natural logarithm", "ln", "exp", "e^x", "Gaussian function"],
      "gloss": "The functions e^x, log₂ x and ln x with their usual rules and growth rates, including the bell curve e^{−x²}."
    },
    {
      "name": "Convergent series and the geometric series",
      "aliases": ["absolutely convergent sum", "infinite sum", "geometric series", "tail bound", "series convergence"],
      "gloss": "Infinite sums as limits of partial sums, with the geometric series Σ r^k = 1/(1−r) for |r|<1 used to bound tails."
    },
    {
      "name": "Prime numbers, coprimality and trial division",
      "aliases": ["relatively prime", "pairwise coprime", "gcd", "odd prime", "primality by trial division", "unique factorization"],
      "gloss": "A prime has no divisors besides 1 and itself, integers are coprime when their gcd is 1, and primality or factors can be found by trying divisors up to the square root."
    },
    {
      "name": "Extended Euclidean algorithm",
      "aliases": ["Euclid's algorithm", "Bezout identity", "computing modular inverses"],
      "gloss": "Euclid's gcd algorithm run backward to write gcd(a,b) = ax + by, which yields modular inverses of units."
    },
    {
      "name": "Counting subsets and binomial coefficients",
      "aliases": ["n choose k", "binomial coefficient", "k-subsets", "inclusion-exclusion", "ground set"],
      "gloss": "The number of k-element subsets of an n-element set is the binomial coefficient C(n,k), and sizes of overlapping sets are counted by inclusion-exclusion."
    },
    {
      "name": "Permutations and permutation matrices",
      "aliases": ["bijection of indices", "reordering of coordinates", "involution", "permutation of positions", "partial permutation"],
      "gloss": "A permutation is a bijective rearrangement of positions, acting on vectors by a 0-1 permutation matrix; an involution is a permutation that is its own inverse."
    },
    {
      "name": "Lexicographic order and Cartesian products of index sets",
      "aliases": ["lexicographic order", "product of ranges", "multi-index", "tuple addressing", "row-major order"],
      "gloss": "Tuples from a product of finite ranges are ordered by comparing the first coordinate, then the next, which is also the row-major order of a multidimensional array."
    },
    {
      "name": "Vector norms, inner products and orthogonality",
      "aliases": ["maximum norm", "sup norm", "infinity norm", "triangle inequality", "dot product", "orthonormal basis", "orthogonal complement", "isometry"],
      "gloss": "Norms measure vector size (for example the maximum of the entries' moduli) and satisfy the triangle inequality, while the dot product defines orthogonality, orthonormal bases and norm-preserving maps (isometries)."
    },
    {
      "name": "Gaussian elimination",
      "aliases": ["row reduction", "row operations", "elementary matrices", "echelon form"],
      "gloss": "Row operations reduce a matrix to echelon form and write an invertible matrix as a product of elementary row operations."
    },
    {
      "name": "Dyadic rationals and binary fractions",
      "aliases": ["dyadic numbers", "numbers m/2^k", "binary point", "fixed-point numbers", "Gaussian dyadics", "Gaussian integers"],
      "gloss": "Dyadic rationals are fractions m/2^k, exactly those with finite binary expansions, and a Gaussian integer is a complex number a+bi with integer a and b."
    },
    {
      "name": "Stable radix sort and counting sort",
      "aliases": ["bit sorting", "stable sorting", "radix sorting", "sorting by a key digit"],
      "gloss": "Sorting records by a small-range key in linear time per pass, keeping equal keys in their original order, so several passes sort by several digits."
    },
    {
      "name": "Mathematical induction",
      "aliases": ["induction on k", "proof by induction", "recursive construction"],
      "gloss": "Proving a statement for all k by proving a base case and showing each case follows from the previous one."
    }
  ]
}
EOF
exegenius submit 0002-background

